\label{tab:crossmodel}
\small
\begin{tabular}{lcccc}
\toprule
Chain type & Macro-F1 & Gen-0 & Gen-1 & Gen-2+ \\
\midrule
Single-model & 0.68 & 0.83 & 0.62 & 0.64 \\
Cross-model & 0.63 & 0.81 & 0.54 & 0.56 \\
\bottomrule
